#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, time, cost;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int V, N, M;
    cin >> V >> N >> M;

    vector<vector<Edge>> graph(N);
    for (int i = 0; i < M; ++i) {
        int a, b, t, p;
        cin >> a >> b >> t >> p;
        --a;
        --b;
        graph[a].push_back({b, t, p});
        graph[b].push_back({a, t, p});
    }

    int X, Y;
    cin >> X >> Y;
    --X;
    --Y;

    const long long INF = LLONG_MAX;
    const int width = V + 1;
    vector<long long> dist(static_cast<size_t>(N) * width, INF);

    using State = tuple<long long, int, int>;
    priority_queue<State, vector<State>, greater<State>> pq;

    dist[X * width] = 0;
    pq.emplace(0, X, 0);

    while (!pq.empty()) {
        auto [time, island, cost] = pq.top();
        pq.pop();

        if (time != dist[island * width + cost]) continue;
        if (island == Y) {
            cout << time << '\n';
            return 0;
        }

        for (const Edge& e : graph[island]) {
            int nextCost = cost + e.cost;
            if (nextCost > V) continue;

            long long nextTime = time + e.time;
            size_t index = static_cast<size_t>(e.to) * width + nextCost;
            if (nextTime < dist[index]) {
                dist[index] = nextTime;
                pq.emplace(nextTime, e.to, nextCost);
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}
